      { name: 'R$/min', value: 'R$ 0,90', goal: 'meta R$ 0,60', verdict: 'bom' },
      { name: 'Lucro líquido', value: 'R$ 13,60', goal: 'meta R$ 10,00', verdict: 'bom' },
