    km: '9,6 km',
    metrics: [
      { name: 'R$/km', value: 'R$ 0,88', goal: 'meta R$ 2,20', verdict: 'ruim' },
      { name: 'R$/hora', value: 'R$ 16,26', goal: 'meta R$ 40,00', verdict: 'ruim' },
      { name: 'R$/min', value: 'R$ 0,27', goal: 'meta R$ 0,60', verdict: 'ruim' },
      { name: 'Lucro líquido', value: 'R$ 0,91', goal: 'meta R$ 10,00', verdict: 'ruim' },
    ],
  },
}

/** Sempre escuro (classe "dark"), independente do tema do app. */
export function OfferCard({ verdict }: { verdict: Verdict }) {
  const v = VERDICT[verdict]
  const offer = OFFERS[verdict]

  return (
    <section
      aria-label={`Oferta de corrida: ${v.label}`}
      className={cn(
        'dark overflow-hidden rounded-[28px] border-4 bg-card text-foreground shadow-2xl',
        v.border,
      )}
    >
      <div className="flex items-center justify-between gap-3 px-4 pt-4">
        <span
          className={cn(
            'inline-flex min-h-11 items-center gap-2 rounded-full px-4 text-xl font-bold text-on-verdict',
            v.fill,
          )}
        >
          <Icon name={v.icon} size={26} fill />
          {v.label}
        </span>
        <span className="text-lg font-bold text-muted-foreground">
          UberX · Uber
        </span>
      </div>

      <div className="flex items-end justify-between gap-3 px-4 pb-4 pt-3">
        <p className="text-[52px] font-bold leading-none tabular-nums">
          {offer.price}
        </p>
        <div className="flex flex-col items-end gap-1 text-xl font-bold tabular-nums">
          <span className="inline-flex items-center gap-1.5">
            <Icon name="schedule" size={24} />
            {offer.time}
          </span>
          <span className="inline-flex items-center gap-1.5">
            <Icon name="route" size={24} />
            {offer.km}
          </span>
        </div>
      </div>

      <ul className="divide-y divide-border border-t border-border">
        {offer.metrics.map((m) => (
          <li
            key={m.name}
            className="flex min-h-16 items-center gap-3 px-4 py-2"
          >
            <VerdictDot verdict={m.verdict} size={32} />
            <span className="flex-1 text-xl font-bold">{m.name}</span>
            <span className="text-right">
              <span className="block text-2xl font-bold leading-tight tabular-nums">
                {m.value}
              </span>
              <span className="block text-base leading-tight text-muted-foreground">
                {m.goal}
              </span>
            </span>
          </li>
        ))}
      </ul>
    </section>
  )
}

import { OfferCard } from '../offer-card'
import { RideBackdrop } from '../ride-backdrop'
import type { ScreenProps, Verdict } from '../config'

export function OfferScreen({ variant }: ScreenProps) {
  return (
    <RideBackdrop>
      <div className="absolute inset-x-3 top-3">
        <OfferCard verdict={variant as Verdict} />
      </div>
    </RideBackdrop>
  )
}

import { cn } from '@/lib/utils'
import { Icon } from './icon'

export type BubbleState = 'ligado' | 'desligado' | 'aviso'

export const BUBBLE_TEXT: Record<
  BubbleState,
  { short: string; long: string }
> = {
  ligado: { short: 'Radar ligado', long: 'Procurando ofertas' },
  desligado: { short: 'Radar desligado', long: 'Toque para ligar' },
  aviso: { short: 'Leitura desligada', long: 'Toque para ligar' },
}

const BADGE: Record<BubbleState, { icon: string; cls: string }> = {
  ligado: { icon: 'check', cls: 'bg-good text-on-verdict' },
  desligado: { icon: 'power_settings_new', cls: 'bg-foreground text-background' },
  aviso: { icon: 'warning', cls: 'bg-warn text-on-verdict' },
}

const BODY: Record<BubbleState, string> = {
  ligado: 'bg-primary text-primary-foreground ring-4 ring-primary/30',
  desligado: 'border-2 border-muted-foreground bg-surface-2 text-muted-foreground',
  aviso: 'border-4 border-warn bg-card text-foreground',
}

/** Bolinha "R": sempre escura/neutra para ficar legível sobre qualquer app. */
export function Bubble({
  state,
  size = 64,
  onClick,
}: {
  state: BubbleState
  size?: number
  onClick?: () => void
}) {
  const badge = BADGE[state]
  const text = BUBBLE_TEXT[state]
  const Tag = onClick ? 'button' : 'span'

  return (
    <Tag
      {...(onClick ? { type: 'button' as const, onClick } : {})}
      aria-label={`${text.short}. ${text.long}.`}
      className="dark relative inline-block rounded-full shadow-xl focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-text"
      style={{ width: size, height: size }}
    >
      <span
        className={cn(
          'grid size-full place-items-center rounded-full font-bold',
          BODY[state],
        )}
        style={{ fontSize: size * 0.5 }}
      >
        R
      </span>
      <span
        className={cn(
          'absolute -bottom-1 -right-1 grid place-items-center rounded-full border-2 border-card',
          badge.cls,
        )}
        style={{ width: size * 0.4, height: size * 0.4 }}
      >
        <Icon name={badge.icon} size={size * 0.26} fill />
      </span>
    </Tag>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'
import { Icon } from '../icon'
import {
  ActionButton,
  ErrorState,
  Group,
  LoadingBlock,
  NavRow,
  ScreenHeader,
  Segmented,
  ToggleRow,
} from '../ui'
import type { ScreenProps, ThemeMode } from '../config'

export function SettingsScreen({
  variant,
  radarOn,
  toggleRadar,
  go,
  retry,
  themeMode,
  setThemeMode,
}: ScreenProps) {
  const [voice, setVoice] = useState({ board: true, arrive: true })
  const [mapOpts, setMapOpts] = useState({
    valetas: true,
    radares: true,
    bons: true,
    eventos: true,
  })
  const [diagnostic, setDiagnostic] = useState(false)
  const [position, setPosition] = useState<'cima' | 'meio' | 'baixo'>('cima')
  const [opacity, setOpacity] = useState(80)
  const [playing, setPlaying] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current)
  }, [])

  const playExample = () => {
    setPlaying(true)
    timer.current = setTimeout(() => setPlaying(false), 2500)
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <ScreenHeader title="Ajustes" />
      <div className="min-h-0 flex-1 overflow-y-auto px-4 pb-8">
        {variant === 'carregando' && (
          <LoadingBlock label="Carregando ajustes…" rows={4} />
        )}
        {variant === 'erro' && (
          <ErrorState
            title="Não deu para carregar os ajustes"
            onRetry={retry}
          />
        )}
        {variant === 'normal' && (
          <>
            <section
              aria-label="Estado da leitura de ofertas"
              className={cn(
                'flex items-center gap-3 rounded-2xl border-[3px] bg-card p-3 pl-4',
                radarOn ? 'border-primary' : 'border-warn',
              )}
            >
              <span
                className={cn(
                  'grid size-12 shrink-0 place-items-center rounded-full',
                  radarOn
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-warn text-on-verdict',
                )}
              >
                <Icon
                  name={radarOn ? 'check_circle' : 'visibility_off'}
                  size={28}
                  fill
                />
              </span>
              <p className="min-w-0 flex-1 text-lg font-bold leading-snug">
                {radarOn
                  ? 'Leitura de ofertas ativa'
                  : 'Leitura de ofertas desligada'}
              </p>
              <ActionButton
                variant={radarOn ? 'secondary' : 'primary'}
                onClick={toggleRadar}
                className="w-auto px-5"
              >
                {radarOn ? 'Desligar' : 'Ligar'}
              </ActionButton>
            </section>

            <button
              type="button"
              className="mt-3 flex min-h-16 w-full items-center gap-3 rounded-2xl bg-surface-2 px-4 py-3 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-text"
            >
              <Icon name="system_update" size={28} className="text-accent-text" />
              <span className="flex-1 text-lg font-bold leading-snug">
                Versão 0.1.85 · toque para baixar e instalar
              </span>
            </button>

            <Group title="Cartão e ganhos">
              <NavRow icon="style" title="Estilo do cartão" value="Completo" />
              <NavRow icon="palette" title="Faixas de cor" value="Bom, médio e ruim" />
              <NavRow icon="preview" title="Prévia do cartão" />
              <NavRow
                icon="play_circle"
                title="Testar cartão na tela"
                onClick={() => go('oferta')}
              />
            </Group>

            <Group title="Voz com o passageiro">
              <ToggleRow
                icon="hail"
                title="Quando embarca"
                description="fala uma boas-vindas"
                checked={voice.board}
                onChange={(v) => setVoice((s) => ({ ...s, board: v }))}
              />
              <ToggleRow
                icon="flag"
                title="Quando chega ao destino"
                description="fala uma despedida"
                checked={voice.arrive}
                onChange={(v) => setVoice((s) => ({ ...s, arrive: v }))}
              />
              <NavRow icon="graphic_eq" title="Voz de estúdio" value="Camila" />
              <NavRow icon="queue_music" title="Mais vozes" />
              <NavRow
                icon={playing ? 'stop_circle' : 'volume_up'}
                title="Ouvir exemplo"
                value={playing ? 'Tocando…' : undefined}
                chevron={false}
                onClick={playExample}
              />
            </Group>

            <Group title="Mapa">
              <ToggleRow
                icon="warning"
                title="Valetas e buracos"
                checked={mapOpts.valetas}
                onChange={(v) => setMapOpts((s) => ({ ...s, valetas: v }))}
              />
              <ToggleRow
                icon="speed"
                title="Radares de velocidade"
                checked={mapOpts.radares}
                onChange={(v) => setMapOpts((s) => ({ ...s, radares: v }))}
              />
              <ToggleRow
                icon="thumb_up"
                title="Pontos bons"
                checked={mapOpts.bons}
                onChange={(v) => setMapOpts((s) => ({ ...s, bons: v }))}
              />
              <ToggleRow
                icon="event"
                title="Eventos de hoje"
                checked={mapOpts.eventos}
                onChange={(v) => setMapOpts((s) => ({ ...s, eventos: v }))}
              />
            </Group>

            <Group title="Custos e gastos">
              <NavRow icon="directions_car" title="Custos do carro" value="R$ 0,23 por km" />
              <NavRow icon="local_gas_station" title="Km por litro" value="11,2 km/l" />
              <NavRow icon="paid" title="Custo real por km" value="R$ 0,78 por km" />
            </Group>

            <Group title="Aparência">
              <div className="p-4">
                <p className="pb-2 text-lg font-bold">Tema</p>
                <Segmented<ThemeMode>
                  label="Tema do aplicativo"
                  value={themeMode}
                  onChange={setThemeMode}
                  options={[
                    { id: 'light', label: 'Claro', icon: 'light_mode' },
                    { id: 'dark', label: 'Escuro', icon: 'dark_mode' },
                    { id: 'auto', label: 'Automático', icon: 'brightness_auto' },
                  ]}
                />
              </div>
              <div className="p-4">
                <p className="pb-2 text-lg font-bold">Posição do card</p>
                <Segmented<'cima' | 'meio' | 'baixo'>
                  label="Posição do cartão na tela"
                  value={position}
                  onChange={setPosition}
                  options={[
                    { id: 'cima', label: 'Em cima', icon: 'vertical_align_top' },
                    { id: 'meio', label: 'No meio', icon: 'vertical_align_center' },
                    { id: 'baixo', label: 'Embaixo', icon: 'vertical_align_bottom' },
                  ]}
                />
              </div>
              <div className="p-4">
                <label
                  htmlFor="opacidade"
                  className="flex items-center justify-between text-lg font-bold"
                >
                  Opacidade da bolinha
                  <span className="tabular-nums">{opacity}%</span>
                </label>
                <input
                  id="opacidade"
                  type="range"
                  min={30}
                  max={100}
                  step={5}
                  value={opacity}
                  onChange={(e) => setOpacity(Number(e.target.value))}
                  className="big-range mt-1"
                />
              </div>
            </Group>

            <Group title="Dados">
              <NavRow icon="history" title="Histórico de ofertas" />
              <NavRow icon="upload_file" title="Importar correção" />
              <ToggleRow
                icon="bug_report"
                title="Modo diagnóstico"
                description="só para falar com o suporte"
                checked={diagnostic}
                onChange={setDiagnostic}
              />
            </Group>
          </>
        )}
      </div>
    </div>
  )
}

